practice.solution:
const items = stdin.trim().split('\n').map(l => l.trim()).filter(Boolean).map(l => {
  const m = l.match(/^h([1-6])\s+(.*)$/i);
  return { level: Number(m[1]), text: m[2].trim() };
});
const issues = [];
let prev = 0;
let h1Count = 0;
items.forEach((h, i) => {
  console.log('  '.repeat(h.level - 1) + '- ' + h.text);
  if (i === 0 && h.level !== 1) issues.push(`first heading is h${h.level}, expected h1`);
  if (i > 0 && h.level > prev + 1) issues.push(`skipped from h${prev} to h${h.level} at '${h.text}'`);
  if (h.level === 1) {
    h1Count++;
    if (h1Count > 1) issues.push(`extra h1 '${h.text}'`);
  }
  prev = h.level;
});
issues.forEach(msg => console.log('Issue: ' + msg));
console.log(issues.length ? `Result: ${issues.length} issue(s)` : 'Result: OK');
